Running smaller queries, each returning only a few rows.

```sql
CREATE OR REPLACE TEMP VIEW r AS SELECT DISTINCT rated_id, rating_type, ccy_basis, rating, outlook, watch, action, valid_from, NULLIF(valid_to,'') AS valid_to FROM ratings;
SELECT count(DISTINCT rated_id) AS inst_ig_now FROM r WHERE rating_type='INST' AND valid_to IS NULL AND rating IN ('AAA','AA+','AA','AA-','A+','A','A-','BBB+','BBB','BBB-');
```
```sql
SELECT count(DISTINCT e.entity_id) AS gb_rated FROM entities e JOIN r ON r.rated_id=e.entity_id WHERE e.country='GB' AND r.rating_type='LTIDR' AND r.valid_to IS NULL AND r.rating NOT IN ('WD','NR');
```
```sql
SELECT string_agg(DISTINCT rated_id, ',') AS dg2026 FROM r WHERE rating_type='LTIDR' AND action='DG' AND valid_from BETWEEN '2026-01-01' AND '2026-12-31';
```
```sql
SELECT string_agg(rated_id, ',') AS lost FROM (SELECT rated_id FROM r WHERE rating_type='LTIDR' GROUP BY rated_id HAVING count(*) FILTER (WHERE valid_to IS NULL AND rating NOT IN ('WD','NR'))=0);
```
